import numpy as np
from scipy.sparse.linalg import eigs, LinearOperator
from numba import njit
@njit(cache=True,fastmath=False)
def csr_mv(data,indices,indptr,x,out):
 for i in range(indptr.size-1):
  s=0.0*x[0]
  for j in range(indptr[i],indptr[i+1]): s += data[j]*x[indices[j]]
  out[i]=s
 return out
class Solver:
 def solve(self,p,**kw):
  A=p['matrix'];n=A.shape[0];k=p['k']; out=np.empty(n,dtype=np.complex128)
  def mv(x): return csr_mv(A.data,A.indices,A.indptr,x,out.copy())
  B=LinearOperator(A.shape,matvec=mv,dtype=A.dtype)
  w,V=eigs(B,k=k,v0=np.ones(n,dtype=A.dtype),ncv=20,maxiter=n*200)
  ix=sorted(range(k),key=lambda i:-abs(w[i]))
  return [V[:,i] for i in ix]
